def __init__(
    self,
    index,
    grouper=None,
    obj=None,
    name=None,
    level=None,
    sort=True,
    observed=False,
    in_axis=False,
):
    self.name = name
    self.level = level
    self.grouper = _convert_grouper(index, grouper)
    self.all_grouper = None
    self.index = index
    self.sort = sort
    self.obj = obj
    self.observed = observed
    self.in_axis = in_axis

    # Set the name if not explicitly provided
    if isinstance(grouper, (Series, Index)) and name is None:
        self.name = grouper.name

    if isinstance(grouper, MultiIndex):
        self.grouper = grouper.values

    # Validate `level` if provided
    if level is not None:
        if isinstance(level, str):
            if level not in index.names:
                raise KeyError(f"Level '{level}' not found in index names.")
            level = index.names.index(level)
        elif not isinstance(level, int):
            raise TypeError("Level must be an integer or a string corresponding to index names.")

        if self.name is None:
            self.name = index.names[level]

        self.grouper, self._labels, self._group_index = index._get_grouper_for_level(
            self.grouper, level
        )

    elif isinstance(self.grouper, Grouper):
        _, grouper, _ = self.grouper._get_grouper(self.obj, validate=False)
        if self.name is None:
            self.name = grouper.result_index.name
        self.obj = self.grouper.obj
        self.grouper = grouper._get_grouper()

    else:
        if self.grouper is None and self.name is not None:
            self.grouper = self.obj[self.name]

        elif isinstance(self.grouper, (list, tuple)):
            self.grouper = com.asarray_tuplesafe(self.grouper)

        elif is_categorical_dtype(self.grouper):
            self.grouper, self.all_grouper = recode_for_groupby(
                self.grouper, self.sort, observed
            )
            categories = self.grouper.categories

            self._labels = self.grouper.codes
            if observed:
                codes = algorithms.unique1d(self.grouper.codes)
                codes = codes[codes != -1]
                if sort or self.grouper.ordered:
                    codes = np.sort(codes)
            else:
                codes = np.arange(len(categories))

            self._group_index = CategoricalIndex(
                Categorical.from_codes(
                    codes=codes, categories=categories, ordered=self.grouper.ordered
                )
            )

        if isinstance(self.grouper, Grouping):
            self.grouper = self.grouper.grouper

        elif not isinstance(
            self.grouper, (Series, Index, ExtensionArray, np.ndarray)
        ):
            if getattr(self.grouper, "ndim", 1) != 1:
                raise ValueError(
                    f"Grouper for '{self.name}' must be 1-dimensional."
                )
            self.grouper = self.index.map(self.grouper)
            if not (
                hasattr(self.grouper, "__len__")
                and len(self.grouper) == len(self.index)
            ):
                raise AssertionError(
                    f"Grouper result violates len(labels) == len(data)"
                )

    if is_datetime64_dtype(self.grouper):
        self.grouper = self.grouper.astype("datetime64[ns]")
    elif is_timedelta64_dtype(self.grouper):
        self.grouper = self.grouper.astype("timedelta64[ns]")
