def __init__(
    self,
    index,
    grouper=None,
    obj=None,
    name=None,
    level=None,
    sort=True,
    observed=False,
    in_axis=False,
):

    self.name = name
    self.level = level
    self.grouper = _convert_grouper(index, grouper)
    self.all_grouper = None
    self.index = index
    self.sort = sort
    self.obj = obj
    self.observed = observed
    self.in_axis = in_axis

    # Validate that the grouper is of a valid type
    if self.grouper is not None and not isinstance(self.grouper, (Series, Index, ExtensionArray, np.ndarray)):
        raise TypeError("Grouper must be a Series, Index, or array-like")

    # Assign name from grouper if not specified
    if isinstance(grouper, (Series, Index)) and name is None:
        self.name = grouper.name

    # Handle MultiIndex
    if isinstance(grouper, MultiIndex):
        self.grouper = grouper.values

    # Handle levels
    if level is not None:
        if not isinstance(level, int):
            if level not in index.names:
                raise KeyError(f"Level '{level}' not in index names.")
            level = index.names.index(level)

        if self.name is None:
            self.name = index.names[level]

        self.grouper, self._labels, self._group_index = index._get_grouper_for_level(self.grouper, level)

    # Handle passed Grouper objects
    elif isinstance(self.grouper, Grouper):
        _, grouper, _ = self.grouper._get_grouper(self.obj, validate=False)
        if self.name is None:
            self.name = grouper.result_index.name
        self.obj = self.grouper.obj
        self.grouper = grouper._get_grouper()

    else:
        # Handle case when grouper is none and name is known
        if self.grouper is None and self.name is not None:
            self.grouper = self.obj[self.name]

        elif isinstance(self.grouper, (list, tuple)):
            self.grouper = com.asarray_tuplesafe(self.grouper)

        # Handle categorical grouper
        elif is_categorical_dtype(self.grouper):
            self.grouper, self.all_grouper = recode_for_groupby(self.grouper, self.sort, observed)
            categories = self.grouper.categories
            self._labels = self.grouper.codes

            if observed:
                codes = algorithms.unique1d(self.grouper.codes)
                codes = codes[codes != -1]
                if sort or self.grouper.ordered:
                    codes = np.sort(codes)
            else:
                codes = np.arange(len(categories))

            self._group_index = CategoricalIndex(
                Categorical.from_codes(codes=codes, categories=categories, ordered=self.grouper.ordered)
            )

        # Ensure grouper is 1-dimensional
        if isinstance(self.grouper, Grouping):
            self.grouper = self.grouper.grouper

        elif not isinstance(self.grouper, (Series, Index, ExtensionArray, np.ndarray)):
            if getattr(self.grouper, "ndim", 1) != 1:
                t = self.name or str(type(self.grouper))
                raise ValueError("Grouper for '{}' not 1-dimensional".format(t))
            self.grouper = self.index.map(self.grouper)
            if not (hasattr(self.grouper, "__len__") and len(self.grouper) == len(self.index)):
                raise AssertionError("Grouper result violates len(labels) == len(data)")

    # Datetime-like groupers should be converted to correct types
    if getattr(self.grouper, "dtype", None) is not None:
        if is_datetime64_dtype(self.grouper):
            self.grouper = self.grouper.astype("datetime64[ns]")
        elif is_timedelta64_dtype(self.grouper):
            self.grouper = self.grouper.astype("timedelta64[ns]")
